// Message types
export interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: Date;
}

// Artifact types
export interface Artifact {
  id: string;
  type: ArtifactType;
  content: string;
  metadata: ArtifactMetadata;
  versions: ArtifactVersion[];
}

export type ArtifactType = 'code' | 'text' | 'data' | 'image' | 'custom';

export interface ArtifactMetadata {
  language?: string;
  filename?: string;
  mimeType?: string;
  tokens?: number;
  custom?: Record<string, unknown>;
}

export interface ArtifactVersion {
  version: number;
  content: string;
  timestamp: Date;
  changeDescription?: string;
}

// LLM Response types
export interface LLMResponse {
  content: string;
  artifact?: Artifact;
  usage: TokenUsage;
  finishReason: FinishReason;
  raw?: unknown;
}

export interface TokenUsage {
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
}

export type FinishReason = 'complete' | 'length' | 'stop' | 'error';

// Streaming types
export interface StreamChunk {
  type: 'text' | 'artifact_start' | 'artifact_delta' | 'artifact_end' | 'done';
  content?: string;
  artifact?: Partial<Artifact>;
}

export interface StreamEvent {
  type: 'iteration_start' | 'chunk' | 'iteration_end' | 'complete' | 'error';
  iteration?: number;
  chunk?: StreamChunk;
  result?: EngineResult;
  error?: Error;
}

// Engine configuration types
export interface EngineConfig {
  adapter: LLMAdapter;
  maxIterations?: number;
  contextManager?: ContextManagerInterface;
  iterationController?: IterationControllerInterface;
  promptAssembler?: PromptAssemblerInterface;
  hooks?: EngineHooks;
}

export interface RunOptions {
  systemPrompt: string;
  userPrompt: string;
  initialArtifact?: Artifact;
  variables?: Record<string, string>;
  stopCondition?: StopCondition;
}

export interface EngineResult {
  artifact: Artifact | null;
  iterations: number;
  history: Message[];
  metrics: ExecutionMetrics;
  stopped: StopReason;
}

export interface ExecutionMetrics {
  totalTokens: number;
  promptTokens: number;
  completionTokens: number;
  totalDuration: number;
  iterationDurations: number[];
}

export type StopCondition = (response: LLMResponse, iteration: number) => boolean;

export type StopReason = 
  | 'max_iterations'
  | 'stop_condition'
  | 'convergence'
  | 'error'
  | 'complete';

// Hook types
export interface EngineHooks {
  beforeIteration?: (iteration: number, context: Message[]) => Promise<void> | void;
  afterIteration?: (iteration: number, response: LLMResponse) => Promise<void> | void;
  onArtifactUpdate?: (artifact: Artifact) => Promise<void> | void;
  onError?: (error: Error, iteration: number) => Promise<void> | void;
}

// Adapter interface
export interface LLMAdapter {
  complete(prompt: string, context: Message[]): Promise<LLMResponse>;
  stream(prompt: string, context: Message[]): AsyncGenerator<StreamChunk>;
  readonly provider: string;
  readonly model: string;
}

// Context manager interface
export interface ContextManagerInterface {
  addMessage(message: Message): void;
  getMessages(): Message[];
  getContextWindow(maxTokens?: number): Message[];
  clear(): void;
  readonly tokenCount: number;
}

// Iteration controller interface
export interface IterationControllerInterface {
  shouldContinue(response: LLMResponse, iteration: number): boolean;
  recordIteration(response: LLMResponse): void;
  reset(): void;
  readonly hasConverged: boolean;
}

// Prompt assembler interface
export interface PromptAssemblerInterface {
  assemble(options: AssembleOptions): string;
}

export interface AssembleOptions {
  systemPrompt: string;
  userPrompt: string;
  artifact?: Artifact;
  variables?: Record<string, string>;
  iteration?: number;
}

// Error types
export class ArtifactEngineError extends Error {
  constructor(
    message: string,
    public code: ErrorCode,
    public cause?: Error
  ) {
    super(message);
    this.name = 'ArtifactEngineError';
  }
}

export type ErrorCode =
  | 'ADAPTER_ERROR'
  | 'CONTEXT_ERROR'
  | 'ITERATION_ERROR'
  | 'VALIDATION_ERROR'
  | 'CONFIGURATION_ERROR';

// Adapter configuration types
export interface AnthropicAdapterConfig {
  apiKey: string;
  model?: string;
  maxTokens?: number;
  temperature?: number;
  baseURL?: string;
}

export interface OpenAIAdapterConfig {
  apiKey: string;
  model?: string;
  maxTokens?: number;
  temperature?: number;
  baseURL?: string;
  organization?: string;
}
